import { loadZipp } from "./zipp.mjs"

const zipp = await loadZipp("./zipp-0.0.28-javascript.wasm")
const sandbox = await zipp.createSandbox({
  limits: { instructions: 50_000_000, timeoutMs: 5000 },
  permissions: {
    storage: { initial: { theme: "dark" } },        // a private, in-memory localStorage
    files: { "notes.txt": "hello" },                 // read with host.callSync("fs.read", ...)
    network: ["https://api.example.com/"],          // the only URLs its fetch() may reach
  },
  host: { "clock.now": () => Date.now() },          // answers host.call("clock.now", ...)
})
const { output } = await sandbox.run(source)       // throws a ZippSandboxError on failure
await sandbox.close()

use zipp_vm::embed::{compile_script, HostValue};

fn main() -> Result<(), String> {
    let source = std::fs::read_to_string("rules.js").map_err(|e| e.to_string())?;
    let mut st = compile_script(&source)?;

    // Host calls are the only way out of the VM, and they are inert until installed.
    st.set_host_call(Box::new(|kind, args| match kind {
        "log" => { println!("{}", args[0]); Ok(HostValue::Undefined) }
        _ => Err(format!("TypeError: unknown host call {kind}")),
    }));

    st.run_init()?;                                   // top-level code, once
    let total = st.eval_in_context("price(42)")?;     // later, same globals
    println!("{total:?}");
    Ok(())
}

